1: using StudentManagement.Core;
2: namespace StudentManagement.Web;
3: public static class WebPresentation
4: {
5:     public static DateOnly BusinessDate=>DateOnly.FromDateTime(DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(9)).DateTime);
6:     public static int SchoolYear=>BusinessDate.Month<4 ? BusinessDate.Year-1 : BusinessDate.Year;
7:     public static string Time(DateTimeOffset value)=>value.ToOffset(TimeSpan.FromHours(9)).ToString("yyyy/MM/dd HH:mm:ss",System.Globalization.CultureInfo.InvariantCulture);
8:     public static object Lookups(LookupSet set,string usage="search",StudentDetail? existing=null,int? year=null,string? grade=null,string? status=null,string? admission=null,string? end=null)
9:     {
10:         if(usage is not ("search" or "register")) throw new WebFault(400,"候補用途が不正です。");
11:         var today=BusinessDate; bool search=usage=="search"; var draft=existing?.Draft;
12:         var codes=set.Codes.Select(c=>new { categoryId=c.CategoryId,value=c.CodeValue,name=c.CodeName,selectable=search||(c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)),note=c.IsActive?"":"停止" });
13:         var classes=set.Classes.Where(c=>(year is null||c.SchoolYear==year)&&(string.IsNullOrEmpty(grade)||c.GradeCode==grade)).Select(c=> {
14:             bool terminal=status is "03" or "04"; bool overlap=DateOnly.TryParse(admission,out var a)&&DateOnly.TryParse(end,out var e)&&c.ValidFrom<=e&&a<=c.ValidTo;
15:             bool active=c.IsActive&&c.ValidFrom<=today&&today<=c.ValidTo; bool same=draft?.ClassId==c.ClassId;
16:             return new { classId=c.ClassId.ToString(System.Globalization.CultureInfo.InvariantCulture),c.SchoolYear,c.GradeCode,gradeName=set.Codes.FirstOrDefault(x=>x.CategoryId=="GRADE"&&x.CodeValue==c.GradeCode)?.CodeName??"不整合",c.ClassCode,c.ClassName,selectable=search||same||(terminal?overlap:active),note=!c.IsActive?"停止":today<c.ValidFrom||today>c.ValidTo?"期間外":"",occupancy=(int?)c.Occupied,c.Capacity };
17:         });
18:         return new { codes,classes,years=set.Classes.Select(c=>c.SchoolYear).Distinct().OrderDescending() };
19:     }
20:     public static object Row(StudentRow r)=>new { studentId=r.StudentId.ToString(System.Globalization.CultureInfo.InvariantCulture),r.StudentNo,r.StudentName,r.StudentNameKana,r.BirthDateWareki,r.SchoolYear,r.GradeName,r.ClassCode,r.ClassName,enrollmentName=r.EnrollmentStatusName,addressDisplay=r.Address,r.PhoneNumber,updatedAt=Time(r.UpdatedAt) };
21:     public static Dictionary<string,string[]> Errors(IEnumerable<FieldError> errors)=>errors.GroupBy(e=>e.Field).ToDictionary(g=>g.Key,g=>g.Select(e=>e.Message).ToArray());
22:     public static object Error(string outcome,string message,string id="E-COM-004",IEnumerable<FieldError>? errors=null,string? requestId=null,bool retry=false)=>new { outcome,messageId=id,message,fieldErrors=Errors(errors??[]),correlationId=requestId??Guid.NewGuid().ToString(),retryBySearch=retry };
23:     public static int Status(Outcome outcome)=>outcome switch { Outcome.Saved=>200,Outcome.NoChange=>200,Outcome.ValidationFailed=>422,Outcome.Forbidden=>403,Outcome.NotFound=>404,Outcome.Conflict or Outcome.ConfirmationRequired=>409,_=>503 };
24:     private static (string Id,string Message) SaveMessage(Outcome outcome)=>outcome switch {
25:         Outcome.Saved=>("I-STU-001","保存しました。"), Outcome.NoChange=>("I-STU-004","変更はありません。"),
26:         Outcome.ConfirmationRequired=>("W-STU-101","同一人物の候補があります。確認してください。"),
27:         Outcome.ValidationFailed=>("E-COM-004","入力を確認してください。"),Outcome.Forbidden=>("E-COM-004","この操作を実行する権限がありません。"),
28:         Outcome.NotFound=>("E-COM-004","対象は存在しません。"),Outcome.Conflict=>("E-COM-004","データが変更されています。再読込してください。"),
29:         Outcome.Unknown=>("E-COM-004","処理結果が不明です。再送せず検索して確認してください。"),_=>("E-COM-004","処理を完了できませんでした。") };
30:     public static object Save(SaveResult r)=>new { outcome=char.ToLowerInvariant(r.Outcome.ToString()[0])+r.Outcome.ToString()[1..],studentId=r.StudentId?.ToString(System.Globalization.CultureInfo.InvariantCulture),rowVersion=r.RowVersion?.ToString(System.Globalization.CultureInfo.InvariantCulture),messageId=r.Errors.FirstOrDefault()?.Code??SaveMessage(r.Outcome).Id,message=r.Errors.FirstOrDefault()?.Message??SaveMessage(r.Outcome).Message,fieldErrors=Errors(r.Errors),correlationId=r.RequestId??Guid.NewGuid().ToString(),retryBySearch=r.Outcome==Outcome.Unknown,duplicateToken=r.ConfirmationToken,candidateCount=r.CandidateCount,candidates=(r.Candidates??[]).Take(20).Select(c=>new { studentId=c.StudentId.ToString(System.Globalization.CultureInfo.InvariantCulture),c.StudentNo,c.StudentName,birthDate=c.BirthDate.ToString("yyyy-MM-dd"),c.BirthDateWareki,classLabel=c.ClassName??"未所属" }) };
31: }
